exec python3 -c 'exec("import itertools,sys\nE=lambda x,y:\"\".join(\"ATGC\"[(a<<1)|b]for a,b in zip(x,y))\ndef machines(n):\n acts=[None]+[(q,b,d)for q in range(-1,n)for b in(0,1)for d in(-1,1)]\n keys=[(q,a)for q in range(n)for a in(0,1)]\n for z in itertools.product(acts,repeat=len(keys)):yield dict(zip(keys,z))\ndef step(M,c):\n q,h,t=c\n if q<0:return c\n z=M.get((q,t.get(h,0)))\n if z is None:return\n q,b,d=z;t=dict(t)\n if b:t[h]=1\n else:t.pop(h,None)\n return q,h+d,t\ndef bits(c):\n q,h,t=c;lo=min([h,*t],default=h);hi=max([h,*t],default=h)\n return \"\".join(str(t.get(i,0))for i in range(lo,hi+1))\ndef run(M,k):\n c=(0,0,{})\n for i in range(k):\n  z=step(M,c)\n  if z is None:return\"CLOSED\",i,\"\"\n  if z==c:return\"FIX\",i,E(bits(c),bits(z))\n  c=z\n return\"OPEN\",k,\"\"\nL=int(sys.argv[1])if len(sys.argv)>1 else 0;r=1\nwhile not L or r<=L:\n o={\"FIX\":0,\"CLOSED\":0,\"OPEN\":0};x=None\n for n in range(1,r+1):\n  for j,M in zip(range(r),machines(n)):\n   s,k,w=run(M,r);o[s]+=1\n   if s==\"FIX\"and x is None:x=n,j,k,w\n print(\"ROUND\",r,*(f\"{k}={v}\"for k,v in o.items()),\"SAMPLE_FIX=\"+repr(x));r+=1")' "$@"
